window.__PAGE_RUNTIME_PARTIALS__["partials/guia-redes-rap03-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA · FPI\u003c/div\u003e\n      \u003ch2\u003eGuía 4 - Documentar las acciones en la red\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinformáticos · Redes (RAP 03)\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda localmente en este navegador.\u003c/p\u003e\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eInformación\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificación\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentación\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eActividades\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128172;\u003c/span\u003e 3.1 Reflexión Inicial \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128269;\u003c/span\u003e 3.2 Contextualización \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128218;\u003c/span\u003e 3.3 Apropiación \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128640;\u003c/span\u003e 3.4 Transferencia \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#control-avance\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#9989;\u003c/span\u003e Control de avance\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128202;\u003c/span\u003e Evidencias\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128279;\u003c/span\u003e Referencias\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cdiv class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\"\u003e\u003cstrong\u003eGuía 4 - Documentar las acciones realizadas en la red\u003c/strong\u003e\u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan\u003e112 horas\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eSanta Bárbara\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\"\u003e\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\"\u003eGuía 4 | Fase: Evaluación · RAP 03\u003c/div\u003e\n        \u003ch1\u003eDocumentar las acciones realizadas en la red\u003c/h1\u003e\n        \u003cp\u003e\n          En las Guías 2 y 3 aprendiste a definir los parámetros de una red y a comprobar su\n          conectividad. Ahora el contexto cambia otra vez: ya no basta con que la red funcione\n          — alguien tiene que dejar constancia escrita de lo que se hizo, cómo se hizo y qué\n          resultados se obtuvieron. Aprenderás a documentar de forma profesional aplicando los\n          estándares TIA-568, TIA-606 e ISO/IEC 11801, y elaborarás el informe técnico completo\n          de la red que ya configuraste.\n        \u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; Documentar las acciones realizadas en la red\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#9201; 112 horas\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; Código: 233108 · V1\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"control-avance\" class=\"section-title\"\u003eTu control de avance\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#9989;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003e\u0026iquest;Qu\u0026eacute; llevas y qu\u0026eacute; te falta?\u003c/h3\u003e\u003cp\u003eSe actualiza solo con tus entregas y respuestas guardadas\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv data-act-std-avance\u003e\u003cp class=\"intro-text\"\u003eCargando tu avance...\u003c/p\u003e\u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n            \u003cp\u003eEsta tabla se marca sola: \u003cstrong\u003eEntregada\u003c/strong\u003e cuando subes la evidencia a Drive y\n            \u003cstrong\u003eGuardada\u003c/strong\u003e cuando guardas tus respuestas. Lo que siga en Pendiente es lo que te falta.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificación de la Guía\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eDatos del Programa de Formación\u003c/h3\u003e\u003cp\u003eInformación oficial del programa y la competencia\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table ident-table\"\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eDenominación del Programa\u003c/td\u003e\u003ctd\u003eTécnico en Sistemas Teleinformáticos\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCódigo del Programa\u003c/td\u003e\u003ctd\u003e233108 · V1\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eNombre del Proyecto Formativo\u003c/td\u003e\u003ctd\u003eAlfabetización digital, asesoría técnica y ciberseguridad para la mejora de actividades productivas locales en la zona de influencia del CIAS.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eFase del Proyecto\u003c/td\u003e\u003ctd\u003eEvaluación\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eActividad del Proyecto\u003c/td\u003e\u003ctd\u003eDocumentar y evaluar el impacto de los servicios y orientaciones prestadas.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCompetencia\u003c/td\u003e\u003ctd\u003e280102129 - Evaluar red de acuerdo con procedimientos de telecomunicaciones y normativa técnica.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eResultado de Aprendizaje\u003c/td\u003e\u003ctd\u003eRAP 03 - Documentar las acciones realizadas en la red de acuerdo con la normativa.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eDuración\u003c/td\u003e\u003ctd\u003e112 horas\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentación\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eEmpieza por aquí:\u003c/strong\u003e conoce de qué trata la guía y qué vas a lograr. Léela completa antes de comenzar las actividades.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e🧭 ¿Cómo trabajar esta guía? Paso a paso\u003c/div\u003e\n        \u003col\u003e\n          \u003cli\u003e\u003cstrong\u003eLee la teoría\u003c/strong\u003e de las secciones de contextualización antes de resolver las actividades.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eResuelve cada actividad\u003c/strong\u003e en orden. Escribe tus respuestas en los campos de la guía.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eGuarda tus respuestas\u003c/strong\u003e con el botón de cada actividad. Tu avance queda guardado en este navegador.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEntrega las evidencias\u003c/strong\u003e que lo pidan con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e. Quedan en la carpeta de tu ficha.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eRevisa \"Tu control de avance\"\u003c/strong\u003e (arriba): te muestra qué llevas Entregado, Guardado y Pendiente.\u003c/li\u003e\n        \u003c/ol\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e💡 Recuerda\u003c/div\u003e\n        \u003cp\u003eNo tienes que terminar todo de una vez: puedes salir y volver, tu trabajo se guarda solo. Si una actividad\n        ya fue entregada y necesitas corregirla, pídele a tu instructor que la habilite de nuevo.\u003c/p\u003e\u003c/div\u003e\n\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eBienvenida a la Guía\u003c/h3\u003e\u003cp\u003eDel «configurar» al «dejar constancia»\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003e\n            Cordial saludo, aprendiz. En las Guías 2 y 3 aprendiste a identificar, configurar y\n            verificar redes informáticas. Ahora el contexto cambia nuevamente: ya no basta con que\n            la red funcione — alguien tiene que dejar constancia escrita de lo que se hizo, cómo se\n            hizo y qué resultados se obtuvieron. Eso es exactamente lo que hace un técnico\n            profesional cada vez que interviene una red.\n          \u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003e\n            Imagina que configuraste la red de \u003cstrong\u003eOccidenteServicios Ltda.\u003c/strong\u003e la semana\n            pasada \u0026mdash;la misma red de la Guía 3\u0026mdash;. Hoy llama otro técnico porque hay una\n            falla nueva. Sin documentación, ese técnico no sabe qué configuraste, qué IPs asignaste,\n            qué contraseñas usaste ni qué pruebas hiciste. Tendría que empezar desde cero, o peor,\n            deshacer lo que hiciste sin saberlo. La documentación no es un trámite: es lo que hace\n            posible el soporte técnico continuo.\n          \u003c/p\u003e\n          \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128204; Lo que aprenderás en esta guía\u003c/div\u003e\n            \u003cp\u003eA documentar de forma profesional usando los estándares TIA-568, TIA-606 e ISO/IEC\n            11801. Elaborarás el informe técnico completo de la red de OccidenteServicios Ltda.\n            que ya configuraste en la Guía 3.\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ 3.1 REFLEXIÓN INICIAL ══════════════ --\u003e\n      \u003cdiv id=\"reflexion\" class=\"section-title\"\u003e3.1 Actividades de Reflexión Inicial\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de reflexión inicial:\u003c/strong\u003e activa lo que ya sabes sobre el tema. Aquí no se evalúa el acierto, sino tu participación: responde con confianza, no hay respuestas malas.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#fff3e0\"\u003e\u0026#128172;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eCaso: el consultorio médico de Tunja\u003c/h3\u003e\u003cp\u003e1 actividad · reflexión individual + plenaria\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003carticle class=\"story-card\"\u003e\n            \u003ch3\u003e\u0026#128736; El caso\u003c/h3\u003e\n            \u003cp\u003eEl técnico Juan terminó de instalar y configurar la red de un consultorio médico en\n            Tunja: 8 computadores, 2 switches, 1 router y una impresora de red. Todo funciona\n            perfectamente. Tres meses después, Juan renunció. La secretaria llama al nuevo técnico\n            porque un computador no puede imprimir. El nuevo técnico llega, revisa el equipo y\n            descubre que alguien cambió la IP \u0026mdash; pero no sabe cuál era la original, qué switch\n            usa ese computador, qué puerto, ni cuál es el gateway. No hay ningún documento.\u003c/p\u003e\n            \u003cp\u003eEl propietario del consultorio perdió medio día de trabajo y pagó 3 horas de soporte\n            técnico para resolver algo que hubiera tardado 5 minutos con documentación.\u003c/p\u003e\n          \u003c/article\u003e\n\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eReflexión individual escrita\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e activar lo que ya sabes sobre documentación técnica a partir del caso del consultorio médico. Producto: reflexión individual de 5 preguntas + notas de la mesa redonda. Responde con tus propias palabras.\u003c/p\u003e\n\n              \u003cdiv class=\"ihelp-trigger\"\u003e\n              \u003cbutton type=\"button\" class=\"ihelp-btn\" data-ihelp-target=\"ihelp-g4-1\"\u003e\n                \u003cspan class=\"ihelp-btn__icon\" aria-hidden=\"true\"\u003e\u0026#128218;\u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__text\"\u003e\n                  \u003cspan class=\"ihelp-btn__kicker\"\u003eMATERIAL DE APOYO INTERACTIVO\u003c/span\u003e\n                  \u003cspan class=\"ihelp-btn__title\"\u003eDocumentar no es \"llenar papeles\"\u003c/span\u003e\n                \u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__arrow\" aria-hidden=\"true\"\u003e\u0026rarr;\u003c/span\u003e\n              \u003c/button\u003e\n              \u003ctemplate id=\"ihelp-g4-1\" data-ihelp-title=\"Documentar no es \u0026quot;llenar papeles\u0026quot;\"\u003e\n                \u003cp\u003eDocumentar una red es dejar por escrito lo que \u003cstrong\u003eotra persona necesitaría saber\u003c/strong\u003e para mantenerla sin tener que adivinar ni repetir tu trabajo: qué IP tiene cada equipo, qué contraseñas quedaron, qué pruebas se hicieron y con qué resultado.\u003c/p\u003e\n                \u003cdiv class=\"ihelp-panel__example\"\u003ePara el consultorio: si Juan hubiera dejado una tabla con la IP y el switch/puerto de cada PC, el nuevo técnico habría resuelto el problema en 5 minutos en vez de perder medio día adivinando.\u003c/div\u003e\n              \u003c/template\u003e\n            \u003c/div\u003e\n\n              \u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Qué documentos debería haber dejado Juan al terminar la instalación? Enumere al menos 4.\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g5r_311_p1\" data-track placeholder=\"Ej.: inventario de dispositivos, tabla de IPs, mapa de puertos, contraseñas...\"\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Qué información específica debe registrarse sobre cada dispositivo de red instalado?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g5r_311_p2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. ¿Alguna vez ha buscado algo que no encontró porque alguien no lo documentó? ¿Qué pasó?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g5r_311_p3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e4. ¿Qué diferencia hay entre un técnico que documenta y uno que no lo hace, desde el punto de vista del cliente?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g5r_311_p4\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e5. ¿Conoce algún formato o plantilla de documentación técnica? ¿Cómo se imagina que debería verse?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g5r_311_p5\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"reflexion311DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarReflexion311\" class=\"btn-save-response\" onclick=\"actStd_save_reflexion311()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_reflexion311()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusReflexion311\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128483; Paso 2 — Mesa redonda\u003c/div\u003e\n                \u003cp\u003eCada aprendiz comparte una respuesta (2-3 minutos). Se construye colectivamente en\n                el tablero una lista de los documentos que debería entregar un técnico al terminar\n                una instalación de red en una MiPyme.\u003c/p\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ 3.2 CONTEXTUALIZACIÓN ══════════════ --\u003e\n      \u003cdiv id=\"contexto\" class=\"section-title\"\u003e3.2 Contextualización e identificación de conocimientos\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de contextualización:\u003c/strong\u003e aquí están los estándares y herramientas que necesitas conocer antes de documentar. Estúdialos con calma.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#ede7f6\"\u003e\u0026#128269;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eBloques A–D: estándares, herramientas y estructura del informe\u003c/h3\u003e\u003cp\u003e4 bloques de estudio + 1 entrega compilada (PDF)\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003eAntes de documentar necesitas conocer los estándares que regulan la\n          documentación de redes y las herramientas que se usan para verificar y certificar el cableado. Explora cada\n          bloque, responde y elabora el producto indicado.\u003c/p\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eBloque A — Estándares de documentación: TIA-568, TIA-606 e ISO/IEC 11801\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e saber qué norma regula qué, para no confundir \"cómo se instala el cable\" (TIA-568) con \"cómo se documenta y etiqueta\" (TIA-606). Producto: tabla comparativa de los 3 estándares.\u003c/p\u003e\n\n              \u003cdiv class=\"ihelp-trigger\"\u003e\n              \u003cbutton type=\"button\" class=\"ihelp-btn\" data-ihelp-target=\"ihelp-g4-2\"\u003e\n                \u003cspan class=\"ihelp-btn__icon\" aria-hidden=\"true\"\u003e\u0026#128218;\u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__text\"\u003e\n                  \u003cspan class=\"ihelp-btn__kicker\"\u003eMATERIAL DE APOYO INTERACTIVO\u003c/span\u003e\n                  \u003cspan class=\"ihelp-btn__title\"\u003e3 normas, 3 preguntas distintas\u003c/span\u003e\n                \u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__arrow\" aria-hidden=\"true\"\u003e\u0026rarr;\u003c/span\u003e\n              \u003c/button\u003e\n              \u003ctemplate id=\"ihelp-g4-2\" data-ihelp-title=\"3 normas, 3 preguntas distintas\"\u003e\n                \u003cul\u003e\n                  \u003cli\u003e\u003cstrong\u003eTIA-568:\u003c/strong\u003e responde \"¿cómo se cablea e instala correctamente?\" (categorías de cable, distancias, orden de hilos).\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eTIA-606:\u003c/strong\u003e responde \"¿cómo se identifica, etiqueta y documenta lo instalado?\" (nombres de dispositivos, rótulos, registros).\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eISO/IEC 11801:\u003c/strong\u003e es la versión internacional (no solo de EE. UU.) de los requisitos generales de cableado, usada cuando el cliente o el proyecto exige un estándar reconocido globalmente.\u003c/li\u003e\n                \u003c/ul\u003e\n                \u003cdiv class=\"ihelp-panel__example\"\u003eEn el consultorio médico: TIA-568 dice cómo debía quedar cableado cada punto de red; TIA-606 es la que exige que cada cable y cada puerto tuviera una etiqueta única, para que el nuevo técnico no tuviera que adivinar cuál era cuál.\u003c/div\u003e\n              \u003c/template\u003e\n            \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-bottom:16px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#127909; Video de referencia\u003c/div\u003e\n                \u003cp\u003e\u003cstrong\u003e¿Qué son los Estándares de Cableado? | ANSI/TIA/EIA, ISO, IEEE\u003c/strong\u003e\u003c/p\u003e\n                \u003ca href=\"https://www.youtube.com/watch?v=xcepAKnPCJA\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\"\u003e\n                  \u0026#9654; Ver en YouTube\n                \u003c/a\u003e\n                \u003cdiv class=\"label\" style=\"margin-top:14px\"\u003e\u0026#128250; Video complementario\u003c/div\u003e\n                \u003cp\u003e\u003cstrong\u003eNorma TIA/EIA 606\u003c/strong\u003e\u003c/p\u003e\n                \u003ca href=\"https://www.youtube.com/watch?v=sMCG22AIanA\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\"\u003e\n                  \u0026#9654; Ver en YouTube\n                \u003c/a\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Qué establece la norma TIA-568 sobre el cableado estructurado en edificios comerciales?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_321_q1\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Qué es la norma TIA-606 y para qué sirve específicamente en el proceso de documentación?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_321_q2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. ¿Qué elementos mínimos debe documentarse según estos estándares al instalar una red?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_321_q3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cp class=\"intro-text\" style=\"font-size:.86rem\"\u003e\u003cstrong\u003eProducto:\u003c/strong\u003e elabora una tabla comparativa de los 3 estándares (TIA-568, TIA-606, ISO/IEC 11801) con las columnas: nombre, qué regula, qué obliga a documentar y aplicación en MiPymes de Boyacá.\u003c/p\u003e\n                \u003cdiv id=\"bloqueA321DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloqueA321\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueA321()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloqueA321\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.2\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eBloque B — Herramientas de verificación y certificación de cableado\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e diferenciar \"verificar que el cable sirve\" (tester) de \"certificar que cumple la norma\" (certificador), para saber cuál usar y cuándo. Producto: cuadro comparativo de 4 herramientas.\u003c/p\u003e\n\n              \u003cdiv class=\"ihelp-trigger\"\u003e\n              \u003cbutton type=\"button\" class=\"ihelp-btn\" data-ihelp-target=\"ihelp-g4-3\"\u003e\n                \u003cspan class=\"ihelp-btn__icon\" aria-hidden=\"true\"\u003e\u0026#128218;\u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__text\"\u003e\n                  \u003cspan class=\"ihelp-btn__kicker\"\u003eMATERIAL DE APOYO INTERACTIVO\u003c/span\u003e\n                  \u003cspan class=\"ihelp-btn__title\"\u003eProbar que funciona vs. certificar que cumple la norma\u003c/span\u003e\n                \u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__arrow\" aria-hidden=\"true\"\u003e\u0026rarr;\u003c/span\u003e\n              \u003c/button\u003e\n              \u003ctemplate id=\"ihelp-g4-3\" data-ihelp-title=\"Probar que funciona vs. certificar que cumple la norma\"\u003e\n                \u003cp\u003eUn \u003cstrong\u003etester\u003c/strong\u003e solo confirma continuidad: \"¿los 8 hilos llegan al otro extremo en el orden correcto?\". Es rápido y barato, pero no mide calidad de la señal.\u003c/p\u003e\n                \u003cp\u003eUn \u003cstrong\u003ecertificador\u003c/strong\u003e (como el Fluke DTX-1800) mide parámetros eléctricos reales (atenuación, NEXT, longitud) y compara contra los límites de la norma TIA-568, entregando un reporte PASS/FAIL formal \u0026mdash;ese reporte es evidencia documentable.\u003c/p\u003e\n                \u003cdiv class=\"ihelp-panel__example\"\u003ePara una instalación pequeña como la papelería de Carmen, un tester basta. Para un proyecto que el cliente exige documentado y certificado (como el consultorio o una empresa grande), se necesita el certificador y su reporte.\u003c/div\u003e\n              \u003c/template\u003e\n            \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-bottom:16px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#127909; Videos de referencia\u003c/div\u003e\n                \u003cp\u003e\u003cstrong\u003eCómo utilizar comprobador o tester de cable de red\u003c/strong\u003e\u003c/p\u003e\n                \u003ca href=\"https://www.youtube.com/watch?v=9oldQLpz5cM\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\"\u003e\n                  \u0026#9654; Ver en YouTube\n                \u003c/a\u003e\n                \u003cdiv class=\"label\" style=\"margin-top:14px\"\u003e\u0026#128250; Video complementario\u003c/div\u003e\n                \u003cp\u003e\u003cstrong\u003eConociendo un Certificador Fluke Networks para Cableado Estructurado\u003c/strong\u003e\u003c/p\u003e\n                \u003ca href=\"https://www.youtube.com/watch?v=kI3Dqg5C1T8\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\"\u003e\n                  \u0026#9654; Ver en YouTube\n                \u003c/a\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Cuál es la diferencia entre un tester de cable y un certificador de cableado? ¿Cuándo usaría cada uno?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_322_q1\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Qué parámetros mide un certificador como el Fluke DTX-1800 que un tester simple no puede medir?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_322_q2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. ¿Qué resultado genera el certificador al finalizar la prueba y cómo se incluye ese resultado en la documentación?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_322_q3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cp class=\"intro-text\" style=\"font-size:.86rem\"\u003e\u003cstrong\u003eProducto:\u003c/strong\u003e elabora un cuadro comparativo de las 4 herramientas (Punch Down, crimpadora, tester de cable y certificador) con las columnas: herramienta, para qué sirve, cuándo se usa en el proceso de instalación y qué genera como evidencia documentable.\u003c/p\u003e\n                \u003cdiv id=\"bloqueB322DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloqueB322\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueB322()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloqueB322\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.3\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eBloque C — Parámetros de certificación de cableado\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e reconocer qué mide cada parámetro del reporte de certificación, para poder leerlo (no solo mirar si dice PASS o FAIL). Producto: tabla de parámetros con valores aceptables.\u003c/p\u003e\n\n              \u003cdiv class=\"ihelp-trigger\"\u003e\n              \u003cbutton type=\"button\" class=\"ihelp-btn\" data-ihelp-target=\"ihelp-g4-4\"\u003e\n                \u003cspan class=\"ihelp-btn__icon\" aria-hidden=\"true\"\u003e\u0026#128218;\u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__text\"\u003e\n                  \u003cspan class=\"ihelp-btn__kicker\"\u003eMATERIAL DE APOYO INTERACTIVO\u003c/span\u003e\n                  \u003cspan class=\"ihelp-btn__title\"\u003eQué mide en realidad un reporte de certificación\u003c/span\u003e\n                \u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__arrow\" aria-hidden=\"true\"\u003e\u0026rarr;\u003c/span\u003e\n              \u003c/button\u003e\n              \u003ctemplate id=\"ihelp-g4-4\" data-ihelp-title=\"Qué mide en realidad un reporte de certificación\"\u003e\n                \u003cul\u003e\n                  \u003cli\u003e\u003cstrong\u003eLongitud:\u003c/strong\u003e que el cable no supere los 100 m del estándar UTP.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eAtenuación:\u003c/strong\u003e cuánta señal se pierde en el trayecto; entre más largo o de peor calidad el cable, más se atenúa.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eNEXT:\u003c/strong\u003e cuánto \"se cuela\" la señal de un par de hilos a otro par vecino dentro del mismo cable (diafonía).\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eBER:\u003c/strong\u003e qué proporción de bits llega con error; entre más bajo, mejor.\u003c/li\u003e\n                \u003c/ul\u003e\n                \u003cdiv class=\"ihelp-panel__example\"\u003eSi un cable pasa la prueba de continuidad (el tester dice que los 8 hilos llegan) pero el certificador marca FAIL por atenuación, significa que el cable físicamente conecta, pero es demasiado largo o de mala calidad para dar la velocidad esperada \u0026mdash;una falla que el tester simple no detecta.\u003c/div\u003e\n              \u003c/template\u003e\n            \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-bottom:16px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#127909; Video de referencia\u003c/div\u003e\n                \u003cp\u003e\u003cstrong\u003e¿Qué es la interferencia NEXT y PS NEXT en Cableado Estructurado?\u003c/strong\u003e\u003c/p\u003e\n                \u003ca href=\"https://www.youtube.com/watch?v=34hyrR9-HbE\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\"\u003e\n                  \u0026#9654; Ver en YouTube\n                \u003c/a\u003e\n                \u003cdiv class=\"label\" style=\"margin-top:14px\"\u003e\u0026#128250; Video complementario\u003c/div\u003e\n                \u003cp\u003e\u003cstrong\u003eCómo interpretar reportes de pruebas de certificación de cableado\u003c/strong\u003e\u003c/p\u003e\n                \u003ca href=\"https://www.youtube.com/watch?v=z-RTVU4gCAU\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\"\u003e\n                  \u0026#9654; Ver en YouTube\n                \u003c/a\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Qué es la atenuación (pérdida de inserción) y cómo afecta el rendimiento de la red?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_323_q1\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Qué significa que un cable tiene un test BER aprobado? ¿Qué implicaciones tiene para la documentación?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_323_q2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. ¿Por qué es importante medir la longitud del cable y registrarla en el informe técnico?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_323_q3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cp class=\"intro-text\" style=\"font-size:.86rem\"\u003e\u003cstrong\u003eProducto:\u003c/strong\u003e completa una tabla de parámetros de certificación (longitud del cable, atenuación / pérdida de inserción, NEXT, retardo en la propagación / Skew, test BER, pérdida de retorno) con las columnas: qué mide y valor aceptable según la norma TIA-568.\u003c/p\u003e\n                \u003cdiv id=\"bloqueC323DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloqueC323\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueC323()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloqueC323\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.4\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eBloque D — Estructura de un informe técnico de red\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e conocer de antemano las secciones que exige un informe técnico, para no dejar ninguna por fuera cuando armes el tuyo en 3.4. Producto: índice comentado de mínimo 8 secciones.\u003c/p\u003e\n\n              \u003cdiv class=\"ihelp-trigger\"\u003e\n              \u003cbutton type=\"button\" class=\"ihelp-btn\" data-ihelp-target=\"ihelp-g4-5\"\u003e\n                \u003cspan class=\"ihelp-btn__icon\" aria-hidden=\"true\"\u003e\u0026#128218;\u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__text\"\u003e\n                  \u003cspan class=\"ihelp-btn__kicker\"\u003eMATERIAL DE APOYO INTERACTIVO\u003c/span\u003e\n                  \u003cspan class=\"ihelp-btn__title\"\u003e¿Para quién escribes: el cliente o el técnico?\u003c/span\u003e\n                \u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__arrow\" aria-hidden=\"true\"\u003e\u0026rarr;\u003c/span\u003e\n              \u003c/button\u003e\n              \u003ctemplate id=\"ihelp-g4-5\" data-ihelp-title=\"¿Para quién escribes: el cliente o el técnico?\"\u003e\n                \u003cp\u003eUn \u003cstrong\u003einforme ejecutivo\u003c/strong\u003e lo lee el dueño del negocio: pocas páginas, sin comandos, enfocado en qué se hizo y qué recomienda. Un \u003cstrong\u003einforme técnico\u003c/strong\u003e lo lee otro técnico: debe traer suficiente detalle (IPs, configuraciones, resultados de pruebas) para que esa persona pueda dar soporte sin volver a preguntarte a ti.\u003c/p\u003e\n                \u003cdiv class=\"ihelp-panel__example\"\u003eEl informe que armarás en la actividad 3.4 es técnico: va dirigido al próximo técnico que atienda OccidenteServicios Ltda., por eso exige la tabla de IPs completa y las 10 pruebas comentadas, no solo un resumen general.\u003c/div\u003e\n              \u003c/template\u003e\n            \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-bottom:16px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#127909; Video de referencia\u003c/div\u003e\n                \u003cp\u003e\u003cstrong\u003e¿Qué es un informe técnico? Aprende a hacer uno paso a paso\u003c/strong\u003e\u003c/p\u003e\n                \u003ca href=\"https://www.youtube.com/watch?v=9UmDB75msPo\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\"\u003e\n                  \u0026#9654; Ver en YouTube\n                \u003c/a\u003e\n                \u003cp style=\"margin-top:10px;font-size:.86rem\"\u003eApoyo: norma ICONTEC para presentación de informes técnicos (NTC 1486).\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Cuál es la diferencia entre un informe técnico y un informe ejecutivo? ¿A quién va dirigido cada uno?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_324_q1\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Qué secciones debe tener obligatoriamente un informe técnico de una instalación de red?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_324_q2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. ¿Qué tipo de evidencias gráficas (capturas, diagramas, fotos) debe incluir un informe técnico de red?\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_324_q3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cp class=\"intro-text\" style=\"font-size:.86rem\"\u003e\u003cstrong\u003eProducto:\u003c/strong\u003e elabora un índice comentado de un informe técnico de red para una MiPyme. Por cada sección escribe su nombre y una frase explicando qué debe contener. Mínimo 8 secciones.\u003c/p\u003e\n                \u003cdiv id=\"bloqueD324DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloqueD324\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueD324()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloqueD324\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv style=\"margin:16px 0;padding:20px 22px;background:#e8f5e9;border:2px solid #2e7d32;border-radius:12px;text-align:center\"\u003e\n            \u003cdiv style=\"font-size:1rem;font-weight:700;color:#1b5e20;margin-bottom:6px\"\u003e\u0026#128196; Exportar contextualización completa\u003c/div\u003e\n            \u003cp style=\"margin:0 0 16px;font-size:.88rem;color:#2e4a2e\"\u003eGuarda las respuestas de los 4 bloques antes de exportar. El documento incluirá los análisis de los Bloques A, B, C y D.\u003c/p\u003e\n            \u003cbutton type=\"button\" onclick=\"actStd_export_exportBloques321a324()\"\n              style=\"display:inline-flex;align-items:center;gap:10px;padding:13px 28px;background:#2e7d32;color:#fff;border:none;border-radius:10px;font-size:1rem;font-weight:700;font-family:inherit;cursor:pointer;box-shadow:0 2px 8px rgba(46,125,50,.35)\"\u003e\n              \u0026#128196; Exportar Bloques A \u0026ndash; D a Word\n            \u003c/button\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.5\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eEntrega — Productos de contextualización (PDF)\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003eCompila los 4 productos (tabla comparativa de estándares,\n              cuadro de herramientas, tabla de parámetros e índice comentado) en un solo PDF y entrégalo a Drive.\u003c/p\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128206; Nombre del archivo\u003c/div\u003e\u003cp\u003e\u003ccode\u003eContextualizacion_Documentacion_NombreAprendiz_FICHA.pdf\u003c/code\u003e\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"entregaContexto\"\u003e\u003c/div\u003e\n              \u003cdiv id=\"entregaContextoGradeMount\" style=\"margin-top:12px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ 3.3 APROPIACIÓN ══════════════ --\u003e\n      \u003cdiv id=\"apropiacion\" class=\"section-title\"\u003e3.3 Actividades de Apropiación\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de apropiación:\u003c/strong\u003e pones en práctica lo aprendido, con las herramientas reales y con la red que ya construiste.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e0f2f1\"\u003e\u0026#128736;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eDemostración práctica de herramientas de cableado\u003c/h3\u003e\u003cp\u003e1 actividad · práctica con Punch Down, crimpadora, tester y certificador\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eDemostración práctica de herramientas de cableado\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e reconocer físicamente las herramientas de instalación y verificación de cableado, y qué evidencia genera cada una para el informe técnico. Producto: registro de las 4 herramientas.\n              Solicita al instructor o monitor del ambiente de aprendizaje\n              las siguientes herramientas. Para cada una, ejecuta el procedimiento indicado y registra el resultado\n              con una captura fotográfica o dibujo (fuera del portal, para tu portafolio), y anota aquí lo observado.\u003c/p\u003e\n\n              \u003cdiv class=\"ihelp-trigger\"\u003e\n              \u003cbutton type=\"button\" class=\"ihelp-btn\" data-ihelp-target=\"ihelp-g4-6\"\u003e\n                \u003cspan class=\"ihelp-btn__icon\" aria-hidden=\"true\"\u003e\u0026#128218;\u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__text\"\u003e\n                  \u003cspan class=\"ihelp-btn__kicker\"\u003eMATERIAL DE APOYO INTERACTIVO\u003c/span\u003e\n                  \u003cspan class=\"ihelp-btn__title\"\u003e4 herramientas, 4 momentos del trabajo\u003c/span\u003e\n                \u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__arrow\" aria-hidden=\"true\"\u003e\u0026rarr;\u003c/span\u003e\n              \u003c/button\u003e\n              \u003ctemplate id=\"ihelp-g4-6\" data-ihelp-title=\"4 herramientas, 4 momentos del trabajo\"\u003e\n                \u003cul\u003e\n                  \u003cli\u003e\u003cstrong\u003ePunch Down:\u003c/strong\u003e inserta a presión los hilos del cable en un patch panel o keystone (toma de pared). Se usa al instalar puntos de red fijos.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eCrimpadora:\u003c/strong\u003e aprieta un conector RJ-45 en la punta de un cable suelto. Se usa para armar cables de parcheo (patch cords).\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eTester:\u003c/strong\u003e se conecta a los dos extremos de un cable ya terminado y confirma, con luces, que los 8 hilos llegan en el orden correcto.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eCertificador:\u003c/strong\u003e mide la calidad eléctrica real del enlace y compara contra la norma TIA-568.\u003c/li\u003e\n                \u003c/ul\u003e\n                \u003cdiv class=\"ihelp-panel__example\"\u003eEl orden natural del trabajo es: primero se instala con Punch Down o crimpadora, después se verifica con el tester, y si el proyecto lo exige, se certifica al final con el certificador.\u003c/div\u003e\n              \u003c/template\u003e\n            \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-bottom:16px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#127909; Videos de referencia\u003c/div\u003e\n                \u003cp\u003e\u003cstrong\u003ePunch Down (patch panel / keystone)\u003c/strong\u003e\u003c/p\u003e\n                \u003ca href=\"https://www.youtube.com/watch?v=hzlMOKY6B4Y\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\"\u003e\n                  \u0026#9654; Ver en YouTube\n                \u003c/a\u003e\n                \u003cp style=\"margin-top:12px\"\u003e\u003cstrong\u003eCrimpadora RJ-45 (T568B)\u003c/strong\u003e\u003c/p\u003e\n                \u003ca href=\"https://www.youtube.com/watch?v=ezjCcv9inmk\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\"\u003e\n                  \u0026#9654; Ver en YouTube\n                \u003c/a\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"table-scroll\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\u003ctr\u003e\u003cth\u003eHerramienta\u003c/th\u003e\u003cth\u003eProcedimiento a ejecutar\u003c/th\u003e\u003cth\u003eEvidencia a registrar\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003ePunch Down (crimpadora de impacto)\u003c/td\u003e\u003ctd\u003eInserta un cable UTP en un patch panel o keystone. Usa la herramienta para insertar correctamente los hilos en el orden T568B.\u003c/td\u003e\u003ctd\u003eFotografía o dibujo del resultado. ¿Quedaron todos los hilos correctamente insertados? ¿Qué pasaría si uno queda suelto?\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eCrimpadora de terminales RJ-45\u003c/td\u003e\u003ctd\u003ePela un cable UTP, organiza los hilos en orden T568B e instala el conector RJ-45 usando la crimpadora.\u003c/td\u003e\u003ctd\u003eFotografía del conector terminado. Orden de colores usado y verificación contra el estándar TIA-568.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eTester de cable de red\u003c/td\u003e\u003ctd\u003eConecta los dos extremos del cable terminado al tester. Observa los indicadores LED de los 8 hilos.\u003c/td\u003e\u003ctd\u003e¿Todos los LEDs encendieron en orden? ¿Qué indica si alguno no enciende o lo hace fuera de orden?\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eCertificador de redes (si está disponible)\u003c/td\u003e\u003ctd\u003eSi el ambiente tiene un certificador, realiza una prueba de certificación en el cable terminado y observa el reporte generado.\u003c/td\u003e\u003ctd\u003eSi no está disponible, analiza el reporte de ejemplo del instructor e identifica los parámetros medidos.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:14px\"\u003e\n                \u003clabel\u003e\u003cspan\u003ePunch Down — resultado y anotaciones\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_331_punchdown\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eCrimpadora RJ-45 — resultado y anotaciones\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_331_crimpadora\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eTester de cable — resultado y anotaciones\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_331_tester\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eCertificador de redes — resultado y anotaciones\u003c/span\u003e\u003ctextarea rows=\"3\" data-store=\"g5r_331_certificador\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"demoHerramientas331DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarDemoHerramientas331\" class=\"btn-save-response\" onclick=\"actStd_save_demoHerramientas331()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_demoHerramientas331()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusDemoHerramientas331\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--recuerda\" style=\"margin-top:14px\"\u003e\u003cdiv class=\"gnote__label\"\u003e💡 Recuerda\u003c/div\u003e\n                \u003cp\u003eLas evidencias de esta práctica (fotografías, anotaciones, resultado del tester) forman parte de tu\n                portafolio y serán referenciadas en el informe técnico final.\u003c/p\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e0f2f1\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003ePlantilla de documentación técnica — Construcción guiada\u003c/h3\u003e\u003cp\u003e3 plantillas · inventario, direccionamiento IP y pruebas de conectividad\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003eUn técnico profesional no escribe su documentación desde cero\n          cada vez — usa plantillas estandarizadas. Completa estas 3 plantillas con los datos reales de la red de\n          OccidenteServicios Ltda. que configuraste en la Guía 3 (Planta 1: 192.168.1.0/24, Planta 2:\n          192.168.2.0/24). Quedarán guardadas en digital y se incluyen directamente en tu informe técnico final.\u003c/p\u003e\n\n          \u003cdiv class=\"ihelp-trigger\"\u003e\n          \u003cbutton type=\"button\" class=\"ihelp-btn\" data-ihelp-target=\"ihelp-g4-7\"\u003e\n            \u003cspan class=\"ihelp-btn__icon\" aria-hidden=\"true\"\u003e\u0026#128218;\u003c/span\u003e\n            \u003cspan class=\"ihelp-btn__text\"\u003e\n              \u003cspan class=\"ihelp-btn__kicker\"\u003eMATERIAL DE APOYO INTERACTIVO\u003c/span\u003e\n              \u003cspan class=\"ihelp-btn__title\"\u003ePor qué usar plantilla y no un párrafo libre\u003c/span\u003e\n            \u003c/span\u003e\n            \u003cspan class=\"ihelp-btn__arrow\" aria-hidden=\"true\"\u003e\u0026rarr;\u003c/span\u003e\n          \u003c/button\u003e\n          \u003ctemplate id=\"ihelp-g4-7\" data-ihelp-title=\"Por qué usar plantilla y no un párrafo libre\"\u003e\n            \u003cp\u003eLa norma TIA-606 exige que la documentación sea \u003cstrong\u003econsistente y fácil de consultar\u003c/strong\u003e \u0026mdash;no un texto narrativo. Por eso se usa una fila por dispositivo, con las mismas columnas siempre: así cualquier técnico nuevo encuentra rápido el dato que necesita, sin leer párrafos.\u003c/p\u003e\n            \u003cdiv class=\"ihelp-panel__example\"\u003eNo necesitas inventar los datos: ya los tienes en la Guía 3 (tabla de direccionamiento del laboratorio de OccidenteServicios). Aquí solo los organizas en el formato que exige un informe técnico profesional.\u003c/div\u003e\n          \u003c/template\u003e\n        \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.2.1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003ePlantilla 1 — Inventario de dispositivos de red\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e dejar un registro único de cada dispositivo (qué es, dónde está, para qué sirve), la base de cualquier soporte futuro. Por cada dispositivo, registra marca/modelo, hostname,\n              interfaz, ubicación y función en la red.\u003c/p\u003e\n              \u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003eR1 — Gi0/0/0 (Router, enlace Planta 1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r1\" data-track placeholder=\"Marca/modelo, hostname, ubicación, función...\"\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eR1 — Gi0/0/1 (Router, enlace Planta 2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eS1 — VLAN 1 (Switch Planta 1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eS2 — VLAN 1 (Switch Planta 2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r4\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC0 — Contabilidad (Planta 1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r5\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC1 — Gerencia (Planta 1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r6\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC2 — Recepción (Planta 1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r7\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC3 — Soporte (Planta 1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r8\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC4 — Bodega (Planta 2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r9\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC5 — Despacho (Planta 2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r10\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC6 — Calidad (Planta 2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r11\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC7 — Sistemas (Planta 2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p1_r12\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"plantilla1InventarioDeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlantilla1Inventario\" class=\"btn-save-response\" onclick=\"actStd_save_plantilla1Inventario()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plantilla1Inventario()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlantilla1Inventario\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.2.2\u003c/span\u003e\u003cspan class=\"activity-title\"\u003ePlantilla 2 — Tabla de direccionamiento IP\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e dejar constancia exacta de cómo quedó direccionada la red, para que un cambio futuro no rompa nada por desconocimiento. Por cada dispositivo, registra dirección IP, máscara de subred, gateway y DNS.\u003c/p\u003e\n              \u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003eR1 — Gi0/0/0 (192.168.1.0/24)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r1\" data-track placeholder=\"IP, máscara, gateway, DNS...\"\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eR1 — Gi0/0/1 (192.168.2.0/24)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eS1 — VLAN 1\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eS2 — VLAN 1\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r4\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC0 — Contabilidad\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r5\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC1 — Gerencia\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r6\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC2 — Recepción\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r7\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC3 — Soporte\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r8\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC4 — Bodega\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r9\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC5 — Despacho\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r10\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC6 — Calidad\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r11\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePC7 — Sistemas\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p2_r12\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"plantilla2IPDeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlantilla2IP\" class=\"btn-save-response\" onclick=\"actStd_save_plantilla2IP()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plantilla2IP()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlantilla2IP\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.2.3\u003c/span\u003e\u003cspan class=\"activity-title\"\u003ePlantilla 3 — Registro de pruebas de conectividad\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e convertir las pruebas que ya ejecutaste en la Guía 3 en evidencia formal y verificable, no solo en algo que \"hiciste una vez\". Registra el resultado (OK / falló) y una observación para\n              cada una de las 10 pruebas de conectividad que ya ejecutaste en la Guía 3.\u003c/p\u003e\n              \u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. PC0: ping 192.168.1.1 (Gateway Planta 1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r1\" data-track placeholder=\"Resultado (OK/falló) y observación...\"\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. PC2: ping 192.168.1.13 (comunicación entre PCs de Planta 1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. PC4: ping 192.168.2.1 (Gateway Planta 2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e4. PC6: ping 192.168.2.13 (comunicación entre PCs de Planta 2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r4\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e5. PC0: ping 192.168.2.10 (enrutamiento Planta 1 \u0026rarr; Planta 2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r5\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e6. PC7: ping 192.168.1.11 (enrutamiento inverso Planta 2 \u0026rarr; Planta 1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r6\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e7. PC3: ping 192.168.1.2 (gestión del switch S1)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r7\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e8. PC5: ping 192.168.2.2 (gestión del switch S2)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r8\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e9. PC0: tracert 192.168.2.13 (ruta entre plantas)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r9\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e10. PC4: telnet 192.168.1.1 (acceso administrativo remoto)\u003c/span\u003e\u003ctextarea rows=\"2\" data-store=\"g5r_p3_r10\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"plantilla3PruebasDeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlantilla3Pruebas\" class=\"btn-save-response\" onclick=\"actStd_save_plantilla3Pruebas()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plantilla3Pruebas()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlantilla3Pruebas\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--recuerda\" style=\"margin-top:14px\"\u003e\u003cdiv class=\"gnote__label\"\u003e💡 Recuerda\u003c/div\u003e\n                \u003cp\u003eEstas 3 plantillas completadas serán incluidas directamente en tu informe técnico final.\n                Guárdalas en formato digital desde ahora.\u003c/p\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ 3.4 TRANSFERENCIA ══════════════ --\u003e\n      \u003cdiv id=\"transferencia\" class=\"section-title\"\u003e3.4 Transferencia del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de transferencia:\u003c/strong\u003e integras todo lo aprendido en esta guía y en las anteriores en un solo producto final.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#fce4ec\"\u003e\u0026#128640;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eInforme técnico completo — OccidenteServicios Ltda.\u003c/h3\u003e\u003cp\u003e1 entrega · producto final del RAP 03\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eInforme técnico completo de la red\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e integrar todo lo trabajado en esta guía (estándares, plantillas, herramientas) en un solo documento profesional que otra persona pueda usar sin tu ayuda. Producto: informe técnico completo en PDF.\u003c/p\u003e\n\n              \u003carticle class=\"story-card\"\u003e\n                \u003ch3\u003e\u0026#128736; El escenario\u003c/h3\u003e\n                \u003cp\u003eFuiste contratado como técnico por OccidenteServicios Ltda. para instalar, configurar\n                y verificar la red de sus oficinas en Puerto Boyacá (2 plantas). Ahora debes entregar a\n                la empresa el informe técnico completo de la intervención, siguiendo los estándares\n                TIA-606 e ISO/IEC 11801.\u003c/p\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"ihelp-trigger\"\u003e\n              \u003cbutton type=\"button\" class=\"ihelp-btn\" data-ihelp-target=\"ihelp-g4-8\"\u003e\n                \u003cspan class=\"ihelp-btn__icon\" aria-hidden=\"true\"\u003e\u0026#128218;\u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__text\"\u003e\n                  \u003cspan class=\"ihelp-btn__kicker\"\u003eMATERIAL DE APOYO INTERACTIVO\u003c/span\u003e\n                  \u003cspan class=\"ihelp-btn__title\"\u003eDe dónde sale cada sección (no partas de cero)\u003c/span\u003e\n                \u003c/span\u003e\n                \u003cspan class=\"ihelp-btn__arrow\" aria-hidden=\"true\"\u003e\u0026rarr;\u003c/span\u003e\n              \u003c/button\u003e\n              \u003ctemplate id=\"ihelp-g4-8\" data-ihelp-title=\"De dónde sale cada sección (no partas de cero)\"\u003e\n                \u003cp\u003eEste informe no se escribe desde cero: casi todo ya lo produjiste en actividades anteriores. Solo hay que ensamblarlo en el orden correcto.\u003c/p\u003e\n                \u003cul\u003e\n                  \u003cli\u003eSecciones 5 y 6 (inventario y direccionamiento) \u0026rarr; copia directo de las Plantillas 1 y 2 (actividad 3.3.2).\u003c/li\u003e\n                  \u003cli\u003eSección 8 (pruebas) \u0026rarr; copia de la Plantilla 3 y las capturas que ya tomaste en la Guía 3.\u003c/li\u003e\n                  \u003cli\u003eSección 4 (descripción de la red) \u0026rarr; exporta el diagrama de topología directo de Packet Tracer (Archivo \u0026rarr; Exportar \u0026rarr; Imagen).\u003c/li\u003e\n                \u003c/ul\u003e\n                \u003cdiv class=\"ihelp-panel__example\"\u003eUna conclusión débil dice solo \"la red funciona bien\". Una conclusión de nivel técnico dice, por ejemplo: \"La red cumple el requerimiento de conectividad entre plantas; se recomienda documentar las contraseñas en un gestor seguro, ya que actualmente solo constan en este informe.\"\u003c/div\u003e\n              \u003c/template\u003e\n            \u003c/div\u003e\n\n              \u003cdiv class=\"table-scroll\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\u003ctr\u003e\u003cth\u003e#\u003c/th\u003e\u003cth\u003eSección\u003c/th\u003e\u003cth\u003eContenido mínimo requerido\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003e1\u003c/td\u003e\u003ctd\u003ePortada\u003c/td\u003e\u003ctd\u003eLogo institucional (SENA), nombre del documento, nombre de la empresa cliente (OccidenteServicios Ltda.), nombre del técnico (aprendiz), número de ficha, fecha de elaboración.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e2\u003c/td\u003e\u003ctd\u003ePalabras clave\u003c/td\u003e\u003ctd\u003eMínimo 5 términos técnicos relevantes (ej.: cableado estructurado, TIA-568, direccionamiento IP, conectividad, hardening).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e3\u003c/td\u003e\u003ctd\u003eIntroducción\u003c/td\u003e\u003ctd\u003eContexto: quién es el cliente, cuál fue el trabajo solicitado, cuál es el alcance del informe. Máximo 1 página.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e4\u003c/td\u003e\u003ctd\u003eDescripción de la red\u003c/td\u003e\u003ctd\u003eDiagrama de topología exportado desde Packet Tracer. Descripción de la arquitectura: número de plantas, segmentos, dispositivos activos.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e5\u003c/td\u003e\u003ctd\u003eInventario de dispositivos\u003c/td\u003e\u003ctd\u003ePlantilla 1 completada: todos los dispositivos con hostname, modelo, interfaz, ubicación y función.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e6\u003c/td\u003e\u003ctd\u003eTabla de direccionamiento IP\u003c/td\u003e\u003ctd\u003ePlantilla 2 completada: todos los dispositivos con IP, máscara, gateway y DNS.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e7\u003c/td\u003e\u003ctd\u003eConfiguración aplicada\u003c/td\u003e\u003ctd\u003eComandos de configuración aplicados en el router y los switches (show running-config resumido). Parámetros de seguridad: hostname, contraseñas, cifrado.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e8\u003c/td\u003e\u003ctd\u003eRegistro de pruebas de conectividad\u003c/td\u003e\u003ctd\u003ePlantilla 3 completada con los resultados de las 10 pruebas. Capturas de pantalla de cada prueba numeradas y comentadas.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e9\u003c/td\u003e\u003ctd\u003eConclusiones\u003c/td\u003e\u003ctd\u003eMínimo 3 conclusiones técnicas: ¿la red cumple los requerimientos? ¿qué recomendarías mejorar? ¿qué normativa se aplicó?\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e10\u003c/td\u003e\u003ctd\u003eBibliografía\u003c/td\u003e\u003ctd\u003eMínimo 4 fuentes citadas en formato APA: normas (TIA-568, TIA-606), documentación de Cisco y fuentes académicas.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128221; Especificaciones de formato\u003c/div\u003e\n                \u003cul style=\"margin:6px 0 0;padding-left:20px\"\u003e\n                  \u003cli\u003eFuente: Arial 11 | Interlineado: 1.15 | Márgenes: 2.5 cm todos los lados.\u003c/li\u003e\n                  \u003cli\u003eExtensión mínima: 8 páginas (sin contar portada ni bibliografía).\u003c/li\u003e\n                  \u003cli\u003eFormato de entrega: PDF.\u003c/li\u003e\n                  \u003cli\u003eEl diagrama de topología debe ser exportado desde Packet Tracer (no dibujado a mano).\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128206; Nombre del archivo\u003c/div\u003e\u003cp\u003e\u003ccode\u003eInformeTecnico_OccidenteServicios_NombreAprendiz_FICHA.pdf\u003c/code\u003e\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"informeTecnico\"\u003e\u003c/div\u003e\n              \u003cdiv id=\"informeTecnicoGradeMount\" style=\"margin-top:12px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ EVIDENCIAS ══════════════ --\u003e\n      \u003cdiv id=\"evidencias\" class=\"section-title\"\u003eEvidencias de Aprendizaje\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eResumen de lo que debes entregar:\u003c/strong\u003e usa esta sección como lista de chequeo final.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--entrega\"\u003e\u003cdiv class=\"gnote__label\"\u003e📦 Antes de entregar, revisa\u003c/div\u003e\n        \u003cul\u003e\n          \u003cli\u003eRespondiste todas las actividades que se piden como evidencia.\u003c/li\u003e\n          \u003cli\u003eTus archivos tienen tu nombre y número de ficha.\u003c/li\u003e\n          \u003cli\u003eSubiste cada evidencia con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e y la ves marcada como \u003cstrong\u003eEntregada\u003c/strong\u003e en tu control de avance.\u003c/li\u003e\n        \u003c/ul\u003e\u003c/div\u003e\n\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\u003cdiv class=\"card-icon\" style=\"background:#e1f5fe\"\u003e\u0026#128202;\u003c/div\u003e\u003cdiv\u003e\u003ch3\u003eProductos y criterios de evaluación\u003c/h3\u003e\u003cp\u003eLo que se evalúa en cada actividad\u003c/p\u003e\u003c/div\u003e\u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\u003ctr\u003e\u003cth\u003eActividad\u003c/th\u003e\u003cth\u003eEvidencia / Producto\u003c/th\u003e\u003cth\u003eInstrumento\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003e3.2 Contextualización (Bloques A–D)\u003c/td\u003e\u003ctd\u003ePDF con los 4 productos: tabla comparativa de estándares, cuadro de herramientas, tabla de parámetros e índice comentado.\u003c/td\u003e\u003ctd\u003eLista de chequeo LC-01\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e3.3.1 Demostración práctica\u003c/td\u003e\u003ctd\u003eRegistro (fotografías/anotaciones) del uso de Punch Down, crimpadora, tester y certificador.\u003c/td\u003e\u003ctd\u003eLista de chequeo LC-02\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e3.3.2 Plantillas 1, 2 y 3\u003c/td\u003e\u003ctd\u003ePlantillas de inventario, direccionamiento IP y pruebas de conectividad, completamente diligenciadas en digital.\u003c/td\u003e\u003ctd\u003eLista de chequeo LC-03\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e3.4 Informe técnico final\u003c/td\u003e\u003ctd\u003eInforme técnico en PDF con topología exportada de Packet Tracer, configuraciones resumidas, tablas diligenciadas y 10 capturas comentadas.\u003c/td\u003e\u003ctd\u003eLista de chequeo LC-04\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eSustentación\u003c/td\u003e\u003ctd\u003eSustentación oral (5–7 min) explicando topología, direccionamiento, pruebas y conclusiones — evaluada en clase por el instructor.\u003c/td\u003e\u003ctd\u003eLC-04 (sustentación)\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ GLOSARIO ══════════════ --\u003e\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario de términos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\u003cdiv class=\"card-icon\" style=\"background:#f3e5f5\"\u003e\u0026#128214;\u003c/div\u003e\u003cdiv\u003e\u003ch3\u003eGlosario\u003c/h3\u003e\u003cp\u003eTérminos clave de la guía\u003c/p\u003e\u003c/div\u003e\u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdl class=\"glossary\"\u003e\n            \u003cdt\u003eCableado estructurado\u003c/dt\u003e\u003cdd\u003eSistema estandarizado de cableado y componentes (cables, conectores, patch panels) que soporta telecomunicaciones en un edificio o campus, siguiendo normas de diseño e instalación.\u003c/dd\u003e\n            \u003cdt\u003eTIA-568\u003c/dt\u003e\u003cdd\u003eFamilia de estándares que define requisitos de cableado de telecomunicaciones y esquemas de terminación (p. ej., T568A/T568B) para garantizar interoperabilidad y desempeño.\u003c/dd\u003e\n            \u003cdt\u003eTIA-606\u003c/dt\u003e\u003cdd\u003eEstándar de administración de infraestructura de telecomunicaciones que define identificación, etiquetado, registro y documentación para asegurar trazabilidad y mantenimiento.\u003c/dd\u003e\n            \u003cdt\u003eISO/IEC 11801\u003c/dt\u003e\u003cdd\u003eSerie de normas internacionales para cableado genérico de instalaciones del cliente, con requisitos generales y categorías/clases de desempeño.\u003c/dd\u003e\n            \u003cdt\u003ePatch panel / Keystone\u003c/dt\u003e\u003cdd\u003eElementos de terminación y distribución del cableado: el patch panel centraliza terminaciones; el keystone es un módulo (jack) donde se termina el par trenzado para toma de red.\u003c/dd\u003e\n            \u003cdt\u003eTester de cable\u003c/dt\u003e\u003cdd\u003eHerramienta básica para verificar continuidad, orden de hilos y fallas comunes (cortos, pares cruzados, abiertos) en cables UTP.\u003c/dd\u003e\n            \u003cdt\u003eCertificador de cableado\u003c/dt\u003e\u003cdd\u003eEquipo que valida el desempeño del enlace frente a una norma (categoría/clase), midiendo parámetros eléctricos y emitiendo un reporte PASS/FAIL.\u003c/dd\u003e\n            \u003cdt\u003eNEXT\u003c/dt\u003e\u003cdd\u003eDiafonía de extremo cercano (Near-End Crosstalk): interferencia entre pares medida en el extremo transmisor; afecta la calidad de la señal.\u003c/dd\u003e\n            \u003cdt\u003eAtenuación (pérdida de inserción)\u003c/dt\u003e\u003cdd\u003ePérdida de potencia de la señal a lo largo del cable; valores altos reducen alcance y calidad del enlace.\u003c/dd\u003e\n            \u003cdt\u003eBER\u003c/dt\u003e\u003cdd\u003eBit Error Rate (tasa de error de bits): proporción de bits erróneos frente a los transmitidos; se usa para validar la integridad de transmisión.\u003c/dd\u003e\n            \u003cdt\u003eGateway\u003c/dt\u003e\u003cdd\u003eDispositivo o dirección IP que enruta el tráfico desde una red local hacia otras redes (salida de la LAN).\u003c/dd\u003e\n            \u003cdt\u003eDNS\u003c/dt\u003e\u003cdd\u003eSistema de nombres de dominio que traduce nombres a direcciones IP, permitiendo acceso por nombres legibles.\u003c/dd\u003e\n            \u003cdt\u003eTelnet\u003c/dt\u003e\u003cdd\u003eProtocolo de acceso remoto en texto plano (no cifrado). Útil en laboratorios; en producción se reemplaza por SSH.\u003c/dd\u003e\n            \u003cdt\u003ePacket Tracer\u003c/dt\u003e\u003cdd\u003eSimulador de redes de Cisco para diseñar, configurar y probar topologías, usado para prácticas y evidencias en la guía.\u003c/dd\u003e\n          \u003c/dl\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ REFERENCIAS ══════════════ --\u003e\n      \u003cdiv id=\"referencias\" class=\"section-title\"\u003eReferentes bibliográficos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\u003cdiv class=\"card-icon\" style=\"background:#eceff1\"\u003e\u0026#128279;\u003c/div\u003e\u003cdiv\u003e\u003ch3\u003eReferencias (IEEE)\u003c/h3\u003e\u003cp\u003eFuentes consultadas\u003c/p\u003e\u003c/div\u003e\u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003col class=\"references\"\u003e\n            \u003cli\u003eTelecommunications Industry Association, «ANSI/TIA-568.0-D — Generic Telecommunications Cabling for Customer Premises», 2020.\u003c/li\u003e\n            \u003cli\u003eTelecommunications Industry Association, «ANSI/TIA-606-C — Administration Standard for Telecommunications Infrastructure», 2017.\u003c/li\u003e\n            \u003cli\u003eInternational Organization for Standardization, «ISO/IEC 11801 — Information technology — Generic cabling for customer premises», 2017.\u003c/li\u003e\n            \u003cli\u003eICONTEC, «NTC 1486 — Documentación. Presentación de tesis, trabajos de grado y otros trabajos de investigación».\u003c/li\u003e\n            \u003cli\u003eCisco Networking Academy, «Networking Basics», Cisco Skills for All.\u003c/li\u003e\n            \u003cli\u003eFluke Networks, «DTX CableAnalyzer Series — User's Manual».\u003c/li\u003e\n            \u003cli\u003eCisco, «Cisco Packet Tracer», netacad.com.\u003c/li\u003e\n            \u003cli\u003eJ. Postel, «Internet Control Message Protocol», RFC 792, 1981.\u003c/li\u003e\n            \u003cli\u003eJ. Postel y J. Reynolds, «TELNET Protocol Specification», RFC 854, 1983.\u003c/li\u003e\n          \u003c/ol\u003e\n          \u003cp class=\"intro-text\" style=\"font-size:.82rem;color:#607d8b;margin-top:12px\"\u003eGuía original: Dubier Orlando Millán Barbosa (Instructor Técnico, CIAS — Regional Boyacá).\u003c/p\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n";
